import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'data/accounts_repository.dart';
class InvoiceQueryState{const InvoiceQueryState({this.contactId,this.search='',this.status});final String? contactId;final String search;final String? status;InvoiceQueryState copyWith({String? contactId,String? search,String? status,bool clearContact=false,bool clearStatus=false})=>InvoiceQueryState(contactId:clearContact?null:(contactId??this.contactId),search:search??this.search,status:clearStatus?null:(status??this.status));}
final invoiceQueryProvider=Provider<InvoiceQueryState>((ref)=>const InvoiceQueryState());final accountsRepositoryProvider=Provider<AccountsRepository>((ref)=>throw UnimplementedError());final invoicesProvider=FutureProvider<List<Invoice>>((ref){final q=ref.watch(invoiceQueryProvider);return ref.read(accountsRepositoryProvider).invoices(status:q.status,q:q.search,contactId:q.contactId);});final accountsPolicyProvider=FutureProvider<CollectionPolicy>((ref)=>ref.read(accountsRepositoryProvider).policy());final accountsApprovalsProvider=FutureProvider<List<Map<String,dynamic>>>((ref)=>ref.read(accountsRepositoryProvider).approvals());
